const SEGMENT_MAP=new Map(SEGMENTS.map(x=>[x.symbol,x]));
const ATLAS=Object.freeze(global.WriterHelperPayloads["writer-helper:ai-brain-creative:ATLAS:1"]);
const ATLAS_META=Object.freeze([{"start":0,"count":7500,"raw_bytes":5490934,"gzip_bytes":580169},{"start":7500,"count":7500,"raw_bytes":5492122,"gzip_bytes":580193},{"start":15000,"count":7500,"raw_bytes":5492053,"gzip_bytes":580245},{"start":22500,"count":7500,"raw_bytes":5490339,"gzip_bytes":579858},{"start":30000,"count":7500,"raw_bytes":5492688,"gzip_bytes":579909},{"start":37500,"count":7500,"raw_bytes":5491620,"gzip_bytes":579648},{"start":45000,"count":7500,"raw_bytes":5490975,"gzip_bytes":579649},{"start":52500,"count":7500,"raw_bytes":5493763,"gzip_bytes":580532},{"start":60000,"count":7500,"raw_bytes":5491951,"gzip_bytes":580389},{"start":67500,"count":7500,"raw_bytes":5491912,"gzip_bytes":580125},{"start":75000,"count":7500,"raw_bytes":5493237,"gzip_bytes":580540},{"start":82500,"count":7500,"raw_bytes":5493423,"gzip_bytes":580312},{"start":90000,"count":7500,"raw_bytes":5491189,"gzip_bytes":579781},{"start":97500,"count":7500,"raw_bytes":5492220,"gzip_bytes":580144},{"start":105000,"count":7500,"raw_bytes":5492441,"gzip_bytes":579783},{"start":112500,"count":7500,"raw_bytes":5490918,"gzip_bytes":579941}]);
const cache=new Map();
const clone=v=>v==null?v:JSON.parse(JSON.stringify(v));
function hash(s){let h=2166136261>>>0;for(const ch of String(s||'')){h^=ch.codePointAt(0);h=Math.imul(h,16777619)>>>0;}return h>>>0;}
async function inflate(parts){const b64=parts.join(''),bin=global.atob?global.atob(b64):Buffer.from(b64,'base64').toString('binary'),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);if(typeof global.DecompressionStream==='function'){const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text());}if(global.pako?.ungzip)return JSON.parse(global.pako.ungzip(bytes,{to:'string'}));throw new Error('Phonology atlas requires DecompressionStream or global pako.');}
async function loadAtlasShard(index=0){index=((Number(index)||0)%ATLAS.length+ATLAS.length)%ATLAS.length;if(cache.has(index))return cache.get(index);const p=inflate(ATLAS[index]);cache.set(index,p);try{return await p}catch(e){cache.delete(index);throw e;}}
async function sampleAtlas(query={},count=8){const seed=hash(JSON.stringify(query)),out=[];for(let n=0;n<count;n++){const si=(seed+n*2654435761)%ATLAS.length,rows=await loadAtlasShard(si),ri=(seed+n*2246822519)%rows.length;out.push(clone(rows[ri]));}return out;}
function features(symbol){return clone(SEGMENT_MAP.get(String(symbol||''))||null);}
function isVowel(s){return SEGMENT_MAP.get(s)?.type==='vowel';}
function isConsonant(s){return SEGMENT_MAP.get(s)?.type==='consonant';}
function tokenize(text){const keys=[...SEGMENT_MAP.keys()].sort((a,b)=>b.length-a.length);const out=[];let i=0,s=String(text||'');while(i<s.length){let found='';for(const k of keys)if(s.startsWith(k,i)){found=k;break;}if(found){out.push(found);i+=found.length;}else{const cp=String.fromCodePoint(s.codePointAt(i));out.push(cp);i+=cp.length;}}return out;}
function featureDistance(a,b){const A=typeof a==='string'?SEGMENT_MAP.get(a):a,B=typeof b==='string'?SEGMENT_MAP.get(b):b;if(!A||!B)return 999;if(A.type!==B.type)return 25;const weights={place:3,manner:4,voice:1,height:3,backness:2,round:1,nasal:2,lateral:2,glottalic:2,airstream:4};let d=0;for(const [k,w] of Object.entries(weights))if(A[k]!==undefined||B[k]!==undefined)d+=(A[k]===B[k]?0:w);return d;}
function nearestSound(symbol,inventory=[]){const source=SEGMENT_MAP.get(symbol)||{symbol,type:/[aeiouəɛɔɪʊɑɒæɐɨɯyøœɤɵɜɞ]/.test(symbol)?'vowel':'consonant'};const candidates=(inventory.length?inventory:SEGMENTS.map(x=>x.symbol)).map(s=>SEGMENT_MAP.get(s)).filter(Boolean);return candidates.map(x=>({symbol:x.symbol,distance:featureDistance(source,x),features:clone(x)})).sort((a,b)=>a.distance-b.distance||a.symbol.localeCompare(b.symbol))[0]||null;}
function naturalClass(criteria={}){return SEGMENTS.filter(s=>Object.entries(criteria).every(([k,v])=>Array.isArray(v)?v.includes(s[k]):s[k]===v)).map(x=>x.symbol);}
function inventoryProfile(inventory=[]){const rows=inventory.map(x=>SEGMENT_MAP.get(typeof x==='string'?x:x.symbol)).filter(Boolean);const c=rows.filter(x=>x.type==='consonant'),v=rows.filter(x=>x.type==='vowel');return {size:rows.length,consonants:c.length,vowels:v.length,places:[...new Set(c.map(x=>x.place))],manners:[...new Set(c.map(x=>x.manner))],hasVoicingContrast:c.some(x=>x.voice)&&c.some(x=>!x.voice),hasClicks:c.some(x=>x.manner==='click'),hasEjectives:c.some(x=>x.manner==='ejective'),hasImplosives:c.some(x=>x.manner==='implosive'),vowelHeights:[...new Set(v.map(x=>x.height))],vowelBackness:[...new Set(v.map(x=>x.backness))],roundedVowels:v.filter(x=>x.round).map(x=>x.symbol),commonness:rows.reduce((a,x)=>(a[x.commonness]=(a[x.commonness]||0)+1,a),{})};}
function parseTemplate(t='(C)V(C)'){return String(t).toUpperCase().replace(/\s+/g,'');}
function checkPhonotactics(word,rules={}){const segs=tokenize(word),issues=[];const maxCluster=Number(rules.maxCluster??2),allowFinal=rules.allowFinalConsonant!==false;let cluster=0;for(let i=0;i<segs.length;i++){if(isConsonant(segs[i])){cluster++;if(cluster>maxCluster)issues.push({type:'cluster',index:i,segment:segs[i],message:`cluster exceeds ${maxCluster}`});}else if(isVowel(segs[i]))cluster=0;}if(!allowFinal&&isConsonant(segs[segs.length-1]))issues.push({type:'final_consonant',index:segs.length-1});const banned=rules.bannedSequences||[];for(const b of banned)if(String(word).includes(b))issues.push({type:'banned_sequence',sequence:b});return {ok:issues.length===0,segments:segs,issues};}
