(function(g){"use strict";const P=g.PeoplePlaces;
const ORDER=['scifi','fantasy','realistic'];
const LABELS={scifi:'Sci-Fi',fantasy:'Fantasy',realistic:'Realistic'};
function normalize(input){let x={realistic:false,fantasy:false,scifi:false};if(Array.isArray(input)){for(const k of input)if(k in x)x[k]=true}else if(input&&typeof input==='object'){for(const k of Object.keys(x))x[k]=input[k]===true}else{x.realistic=true}if(!x.realistic&&!x.fantasy&&!x.scifi)x.realistic=true;return x}
function selected(input){const x=normalize(input);return ORDER.filter(k=>x[k])}
function weightRows(input){const x=normalize(input),n=selected(x);if(n.length===1)return[{id:n[0],weight:1}];if(x.scifi&&x.fantasy&&x.realistic)return[{id:'scifi',weight:.72},{id:'fantasy',weight:.23},{id:'realistic',weight:.05}];if(x.scifi&&x.fantasy)return[{id:'scifi',weight:.76},{id:'fantasy',weight:.24}];if(x.scifi&&x.realistic)return[{id:'scifi',weight:.86},{id:'realistic',weight:.14}];if(x.fantasy&&x.realistic)return[{id:'fantasy',weight:.82},{id:'realistic',weight:.18}];return n.map(id=>({id,weight:1/n.length}))}
function layering(input){const x=normalize(input);if(x.scifi&&x.fantasy&&x.realistic)return{frame:'interstellar',primary:'Sci-Fi / alien civilization frame',secondary:'Fantasy enclaves, guilds, magical settlements, and traditions',tertiary:'Grounded realistic everyday people, institutions, and districts'};if(x.scifi&&x.fantasy)return{frame:'science-fantasy',primary:'Sci-Fi / alien civilization frame',secondary:'Fantasy enclaves, guilds, magical settlements, and traditions',tertiary:null};if(x.scifi&&x.realistic)return{frame:'grounded-scifi',primary:'Sci-Fi / alien civilization frame',secondary:'Grounded realistic civilian layer',tertiary:null};if(x.fantasy&&x.realistic)return{frame:'grounded-fantasy',primary:'Fantasy realm and magical-settlement frame',secondary:'Grounded realistic everyday layer',tertiary:null};if(x.scifi)return{frame:'scifi',primary:'Sci-Fi / alien civilization frame',secondary:null,tertiary:null};if(x.fantasy)return{frame:'fantasy',primary:'Fantasy realm and magical-settlement frame',secondary:null,tertiary:null};return{frame:'realistic',primary:'Realistic contemporary / user-defined frame',secondary:null,tertiary:null}}
function profile(input){const modes=normalize(input),rows=weightRows(modes),primary=rows.slice().sort((a,b)=>b.weight-a.weight||ORDER.indexOf(a.id)-ORDER.indexOf(b.id))[0]?.id||'realistic';return{modes,selected:selected(modes),primary,weights:Object.fromEntries(rows.map(x=>[x.id,x.weight])),hierarchy:['scifi','fantasy','realistic'],layers:layering(modes),rule:'Sci-Fi is dominant whenever selected; fantasy is secondary-dominant when Sci-Fi is absent or alongside it; realism is dominant only when selected by itself.'}}
function pickMode(random,input){const rows=Array.isArray(input)?weightRows(input):input?.weights?Object.entries(input.weights).map(([id,weight])=>({id,weight})):weightRows(input);return random.weighted(rows)?.id||'realistic'}
function allocateModes(random,input,count){count=Math.max(0,Math.floor(Number(count)||0));if(!count)return[];const rows=input?.weights?Object.entries(input.weights).map(([id,weight])=>({id,weight})):weightRows(input);const exact=rows.map((x,i)=>({...x,i,raw:x.weight*count,count:Math.floor(x.weight*count)}));let assigned=exact.reduce((n,x)=>n+x.count,0);const remainder=exact.slice().sort((a,b)=>(b.raw-b.count)-(a.raw-a.count)||ORDER.indexOf(a.id)-ORDER.indexOf(b.id));for(let i=0;assigned<count;i++,assigned++)remainder[i%remainder.length].count++;
// If the population is large enough for every selected layer to appear, preserve at least one representative.
if(count>=rows.length*6){for(const row of exact){if(row.count===0){const donor=exact.slice().sort((a,b)=>b.count-a.count||ORDER.indexOf(a.id)-ORDER.indexOf(b.id))[0];if(donor&&donor.count>1){donor.count--;row.count++}}}}
const out=[];for(const id of ORDER){const row=exact.find(x=>x.id===id);for(let i=0;i<(row?.count||0);i++)out.push(id)}return random?.shuffle?random.shuffle(out):out}
function label(mode){return LABELS[mode]||'Realistic'}
function summary(input){const p=input?.primary?input:profile(input),weights=p.weights||{};const parts=p.selected.map(k=>`${label(k)} ${Math.round((weights[k]||0)*100)}%`);return `${p.selected.map(label).join(' + ')} • primary: ${label(p.primary)}${p.selected.length>1?' • target mix '+parts.join(' / '):''}`}
P.register('WorldModeEngine',{ORDER,LABELS,normalize,selected,weightRows,layering,profile,pickMode,allocateModes,label,summary});})(window);



