(function(g){"use strict";const P=g.PeoplePlaces,D=P.SpeculativeData;
function cap(s){return s?String(s).charAt(0).toUpperCase()+String(s).slice(1):''}
function collapse(s){return String(s).replace(/([a-z])\1\1+/gi,'$1$1').replace(/([aeiou])\1+/gi,'$1')}
function profileFor(type){return D.nameProfiles[type.profile]||D.nameProfiles.humanic}
function ending(style,p,r){const key=style==='masculine'?'masc':style==='feminine'?'fem':'neut';return r.pick(p[key]||p.neut||[''])}
function coreName(p,style,r){const min=Math.max(1,p.syllables?.[0]||2),max=Math.min(4,p.syllables?.[1]||3),syl=r.int(min,max),useEnding=r.chance(.72);let out='',body=Math.max(1,useEnding?syl-1:syl);for(let i=0;i<body;i++){out+=(r.pick(p.onset)||'')+(r.pick(p.nucleus)||'a');if(!useEnding&&i===body-1&&r.chance(.55))out+=r.pick(p.coda)||''}if(useEnding)out+=ending(style,p,r);out=collapse(out).replace(/[aeiouy]{3,}/gi,m=>m.slice(0,2)).replace(/[^a-z'’\-]/gi,'');if(out.length>18)out=out.slice(0,18).replace(/[bcdfghjklmnpqrstvwxyz]+$/i,'');return cap(out||'Ari')}
function compound(r,genre){if(genre==='scifi')return r.pick(['Nova','Vector','Helix','Aster','Ion','Solar','Vesper','Zenith','Echo','Pioneer'])+r.pick(['line','core','axis','node','wake','ray','point','arc','shift','mark']);return r.pick(D.surnameWords.prefix)+r.pick(D.surnameWords.suffix)}
function epithet(r,genre){if(genre==='scifi')return 'the '+r.pick(['Far','First','Ion','Outer','Silent','Solar','Stellar','Vector'])+' '+r.pick(['Signal','Walker','Witness','Drift','Voice','Navigator','Relay','Mind']);return 'the '+r.pick(['Ashen','Bright','Far','Frost','Green','Iron','Moon','Quiet','Red','Silver','Star','Stone','Storm','Swift','Thorn','Wild'])+' '+r.pick(['Brow','Eye','Heart','Mantle','Runner','Song','Step','Voice','Walker','Watch','Wind'])}
function identifier(type,r){const prefixes=type.nameFormat==='collective'?['NODE','CHOIR','MESH','SWARM','LINK','MIND']:(type.nameFormat||'').includes('synthetic')?['UNIT','SYN','CORE','AX','RX','NX','DV']:['ID','REF','SIG'];return `${r.pick(prefixes)}-${r.int(1,999)}${r.chance(.35)?String.fromCharCode(65+r.int(0,25)):''}`}
function secondName(type,mode,style,r){if(mode==='none')return{value:'',role:null};if(mode==='auto'||!mode){if(type.genre==='scifi'&&(type.nameFormat||'').includes('synthetic'))mode=r.pick(['identifier','identifier','family','none']);else if(type.nameFormat==='collective')mode=r.pick(['identifier','identifier','compound','none']);else mode=r.pick(['family','compound','compound','epithet','none','identifier'])}if(mode==='identifier')return{value:identifier(type,r),role:'designation'};if(mode==='compound')return{value:compound(r,type.genre),role:'family'};if(mode==='epithet')return{value:epithet(r,type.genre),role:'byname'};if(mode==='none')return{value:'',role:null};return{value:coreName(profileFor(type),style,r),role:'family'}}
function firstName(type,style,r){const base=coreName(profileFor(type),style,r);if(type.genre==='scifi'&&type.nameFormat==='synthetic'&&r.chance(.58))return `${base}-${r.int(1,99)}`;if(type.genre==='scifi'&&type.nameFormat==='collective'&&r.chance(.45))return `${base} ${r.pick(['Node','Chorus','Mesh','Cluster','Link'])} ${r.int(1,99)}`;return base}
function generate(random,type,opts={}){const r=random.fork('speculative-name'),style=opts.namePresentation||r.pick(['neutral','neutral','masculine','feminine']),first=firstName(type,style,r),second=secondName(type,opts.surnameMode||'auto',style,r),full=second.value?(second.role==='byname'?`${first}, ${second.value}`:`${first} ${second.value}`):first;return{first,middle:null,last:second.role==='family'?second.value:null,full,givenNames:[first],middleNames:[],familyNames:second.role==='family'?[second.value]:[],components:[{role:'given',value:first},...(second.value?[{role:second.role,value:second.value}]:[])],locale:null,language:null,region:null,script:'fictional',order:second.value?'given-secondary':'given',structure:{id:`${type.genre}-speculative`,middleRole:null,order:second.value?['given',second.role]:['given'],phoneticProfile:type.profile},pairing:{method:'speculative phonotactic profile; independent of gender identity, personality, occupation, or appearance',analyses:[]},context:{kind:'speculative',genre:type.genre,label:`${P.WorldModeEngine.label(type.genre)} procedural naming`,sentientType:type.name,profile:type.profile,namePresentation:style,stereotypeGuardrails:['No human culture inferred from species','No identity-to-name inference','No personality-to-name inference','No occupation/class-to-name inference']}}}
P.register('SpeculativeNameEngine',{generate,coreName});})(window);


