function score(first,middle,last,opts={}){if(!middle||plain(first)===plain(middle))return{score:-99,reasons:['duplicate name'],publicSources:[]};let total=0,reasons=[];const profile=opts.phoneticProfile||'light',language=String(opts.language||'').split(/[-_]/)[0];if(profile==='english'||language==='en'){const r=rhythm(first,middle);total+=r.score;reasons.push(...r.reasons);const e=eraScore(first,middle);total+=e.score;reasons.push(...e.reasons);const c=commonMiddleScore(middle);if(c){total+=c;reasons.push('documented as a commonly used middle name in a public survey')}const pe=publicEvidence(first,middle);if(pe.score){total+=pe.score;reasons.push('directional public pairing evidence')}const sm=seam(first,middle);total+=sm.score;reasons.push(...sm.reasons);total+=rhymePenalty(first,middle);if(last){const ml=seam(middle,last);total+=ml.score*.65;if(ml.score<0)reasons.push('middle-to-family-name seam needs care')}}else if(profile==='romance-light'||profile==='light'){const sm=seam(first,middle);total+=sm.score*.5;total+=rhymePenalty(first,middle)*.5;reasons.push(...sm.reasons)}
if(plain(first)[0]===plain(middle)[0]){total-=.5;reasons.push('alliterative initials')}return{score:Math.round(total*100)/100,reasons:[...new Set(reasons)],publicSources:publicEvidence(first,middle).sources,firstSyllables:englishSyllables(first),middleSyllables:englishSyllables(middle)}}
function rank(first,candidates,last,opts={}){const seen=new Set(),rows=[];for(const c of candidates||[]){if(!c||seen.has(c)||plain(c)===plain(first))continue;seen.add(c);rows.push({name:c,...score(first,c,last,opts)})}rows.sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name));return rows}
